import GallerySectionV4 from "./components/gallery-section-v4"

export default function Page() {
  return <GallerySectionV4 />
}

import { GalleryMasonryItem } from "./gallery-masonry-item"
import { createBlockImage } from "@/lib/block-media"
import { ROW_UNIT, imageFiles, type GalleryItem } from "../lib/config"

const blockImage = createBlockImage("gallery-section-v4")
const galleryItems: GalleryItem[] = imageFiles.map(
  ({ file, alt, heightPx }, index) => ({
    id: `image-${index + 1}`,
    alt,
    span: Math.round(heightPx / ROW_UNIT),
    imageSrc: blockImage(file),
  }),
)

export type GallerySectionV4Props = {
  items?: GalleryItem[]
}

export default function GallerySectionV4({
  items = galleryItems,
}: GallerySectionV4Props = {}) {
  return (
    <section className="py-4 md:py-6 lg:py-8">
      <div className="mx-auto max-w-7xl px-4">
        <div className="grid grid-flow-dense auto-rows-[4px] grid-cols-2 gap-x-4 md:grid-cols-3 lg:grid-cols-4">
          {items.map((item, index) => (
            <GalleryMasonryItem
              key={item.id}
              item={item}
              priority={index < 4}
            />
          ))}
        </div>
      </div>
    </section>
  )
}

"use client"

import { useState } from "react"
import Image from "next/image"

import { useInView } from "../hooks/use-in-view"
import type { GalleryItem } from "../lib/config"

type GalleryMasonryItemProps = {
  item: GalleryItem
  priority?: boolean
}

export function GalleryMasonryItem({
  item,
  priority = false,
}: GalleryMasonryItemProps) {
  const [loaded, setLoaded] = useState(false)
  const [ref, inView] = useInView<HTMLDivElement>()
  const revealed = loaded && inView

  return (
    <div style={{ gridRowEnd: `span ${item.span}` }}>
      <div
        ref={ref}
        className="relative h-[calc(100%-1rem)] overflow-hidden rounded-lg bg-muted"
      >
        <Image
          src={item.imageSrc}
          alt={item.alt}
          fill
          unoptimized
          priority={priority}
          sizes="(max-width: 640px) 50vw, (max-width: 1024px) 33vw, 25vw"
          className={`object-cover transition-[opacity,filter,translate] duration-500 ease-out${revealed ? " translate-y-0 opacity-100 blur-none" : " translate-y-6 opacity-0 blur-sm"}`}
          onLoad={() => setLoaded(true)}
          onError={() => setLoaded(true)}
        />
      </div>
    </div>
  )
}

"use client"

import { useEffect, useRef, useState } from "react"

/** Flips to `true` once the node crosses into the viewport, then stops observing. */
export function useInView<T extends HTMLElement>(threshold = 0.15) {
  const ref = useRef<T>(null)
  const [inView, setInView] = useState(false)

  useEffect(() => {
    const node = ref.current
    if (!node) return

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (!entry.isIntersecting) return
        setInView(true)
        observer.disconnect()
      },
      { threshold, rootMargin: "0px 0px -10% 0px" },
    )

    observer.observe(node)
    return () => observer.disconnect()
  }, [threshold])

  return [ref, inView] as const
}
